  "transcript": {
    "segments": [
      {
        "start": 0,
        "end": 1.6,
        "text": "嗨 大家好 神神"
      },
      {
        "start": 1.6,
        "end": 2.6,
        "text": "今天這條視頻呢"
      },
      {
        "start": 2.6,
        "end": 3.44,
        "text": "討論一個月"
      },
      {
        "start": 3.44,
        "end": 4.8,
        "text": "當你徹底了解AI"
      },
      {
        "start": 4.8,
        "end": 6.96,
        "text": "包括它的本質 發展式"
      },
      {
        "start": 6.96,
        "end": 8.28,
        "text": "當今的發展運用"
      },
      {
        "start": 8.28,
        "end": 9.48,
        "text": "以及作為普通人"
      },
      {
        "start": 9.48,
        "end": 11.88,
        "text": "我們能利用AI把握哪些發展機率"
      },
      {
        "start": 11.88,
        "end": 13.96,
        "text": "零基礎小巴也可以全程理解"
      },
      {
        "start": 13.96,
        "end": 15.64,
        "text": "詳細介紹 剛貨滿滿"
      },
      {
        "start": 15.64,
        "end": 16.48,
        "text": "C.I.開始吧"
      },
      {
        "start": 21.68,
        "end": 24.28,
        "text": "AI是RGP-SHOINTITIONS的檢稱"
      },
      {
        "start": 24.28,
        "end": 25.52,
        "text": "也就是員工智能"
      },
      {
        "start": 25.52,
        "end": 26.76,
        "text": "它是一套機率數據的"
      },
      {
        "start": 26.76,
        "end": 28.08,
        "text": "複雜算法和系統"
      },
      {
        "start": 28.08,
        "end": 29,
        "text": "大白話說"
      },
      {
        "start": 29,
        "end": 30.6,
        "text": "就像你將小孩認經過"
      },
      {
        "start": 30.6,
        "end": 31.88,
        "text": "會將它看顏色"
      },
      {
        "start": 31.88,
        "end": 34.4,
        "text": "熱型狀 摸手感 常味道"
      },
      {
        "start": 34.4,
        "end": 36.2,
        "text": "下次它看到蘋果就認識了"
      },
      {
        "start": 36.2,
        "end": 37.24,
        "text": "AI也一樣"
      },
      {
        "start": 37.24,
        "end": 39.4,
        "text": "只是從小孩變成了電腦程序"
      },
      {
        "start": 39.4,
        "end": 41.56,
        "text": "你給AI看一百萬張貓的圖片"
      },
      {
        "start": 41.56,
        "end": 43.2,
        "text": "它會通過算法自動總結出"
      },
      {
        "start": 43.2,
        "end": 46.12,
        "text": "貓有監耳朵 鬍鬚 尾巴等特徵"
      },
      {
        "start": 46.12,
        "end": 47.28,
        "text": "下次看到新圖片"
      },
      {
        "start": 47.28,
        "end": 48.88,
        "text": "它就能判斷是不是貓"
      },
      {
        "start": 48.88,
        "end": 49.8,
        "text": "不過一樣明確"
      },
      {
        "start": 49.8,
        "end": 51.52,
        "text": "AI的判斷是基於數字"
      },
      {
        "start": 51.52,
        "end": 53.52,
        "text": "統計學的數據推理得出的"
      },
      {
        "start": 53.52,
        "end": 55.4,
        "text": "和人類擁有自主邏輯思維"
      },
      {
        "start": 55.4,
        "end": 56.48,
        "text": "情感一失"
      },
      {
        "start": 56.48,
        "end": 58.28,
        "text": "主觀認知有本質的區別"
      },
      {
        "start": 58.28,
        "end": 60.16,
        "text": "AI還有三層核心結構"
      },
      {
        "start": 60.16,
        "end": 61.56,
        "text": "分為基礎設施層"
      },
      {
        "start": 61.56,
        "end": 63.4,
        "text": "算法模型層和應用層"
      },
      {
        "start": 64.36,
        "end": 67.12,
        "text": "它分為芯片 服務器 雲計算"
      },
      {
        "start": 67.12,
        "end": 68.76,
        "text": "是AI的算例裏做"
      },
      {
        "start": 68.76,
        "end": 72.56,
        "text": "芯片主要分為GPU TPU MPU3類"
      },
      {
        "start": 72.56,
        "end": 74.36,
        "text": "GPU是當前的芯片王者"
      },
      {
        "start": 74.36,
        "end": 75.84,
        "text": "是當今擁有最成熟"
      },
      {
        "start": 75.84,
        "end": 77.36,
        "text": "強大的算法硬件"
      },
      {
        "start": 77.36,
        "end": 78.4,
        "text": "吐用性高"
      },
      {
        "start": 78.4,
        "end": 80.52,
        "text": "AI 圖形 計算等同時"
      },
      {
        "start": 80.52,
        "end": 83.2,
        "text": "集中主要的玩家是音尾達和AMD"
      },
      {
        "start": 83.2,
        "end": 86.72,
        "text": "TPU是補個專為AI訓練設計的芯片"
      },
      {
        "start": 86.72,
        "end": 88.72,
        "text": "不對外賣 相對封閉"
      },
      {
        "start": 88.72,
        "end": 90.92,
        "text": "主用在谷歌和自己的AI業務"
      },
      {
        "start": 90.92,
        "end": 93.12,
        "text": "但能為谷歌AI生態提供穩定"
      },
      {
        "start": 93.12,
        "end": 94.72,
        "text": "據量低層本的算例"
      },
      {
        "start": 94.72,
        "end": 99.03999999999999,
        "text": "NPU是手機芯片中層在AI運算的核心單元"
      },
      {
        "start": 99.03999999999999,
        "end": 101.24000000000001,
        "text": "華為70 蘋果AGA"
      },
      {
        "start": 101.24000000000001,
        "end": 103.44,
        "text": "高通銷容等主流手機芯片"
      },
      {
        "start": 103.44,
        "end": 105.84,
        "text": "內部軍形成了專屬的NPU模板"
      },
      {
        "start": 105.84,
        "end": 106.8,
        "text": "服務器的話"
      },
      {
        "start": 106.8,
        "end": 108.28,
        "text": "就像層在AI的身體"
      },
      {
        "start": 108.28,
        "end": 109.6,
        "text": "都會國際巨頭"
      },
      {
        "start": 109.6,
        "end": 111.6,
        "text": "Dire 惠普 超威"
      },
      {
        "start": 111.6,
        "end": 112.84,
        "text": "雲場上自言"
      },
      {
        "start": 112.84,
        "end": 114.75999999999999,
        "text": "谷歌 亞馬遜 威延"
      },
      {
        "start": 114.75999999999999,
        "end": 115.84,
        "text": "國內搶商"
      },
      {
        "start": 115.84,
        "end": 116.88,
        "text": "浪逃 信息"
      },
      {
        "start": 116.88,
        "end": 118.08,
        "text": "華為AGA的系列"
      },
      {
        "start": 118.08,
        "end": 119.32,
        "text": "新華山"
      },
      {
        "start": 119.32,
        "end": 119.96000000000001,
        "text": "注意了"
      },
      {
        "start": 119.96000000000001,
        "end": 121.68,
        "text": "這些不是普通服務器"
      },
      {
        "start": 121.68,
        "end": 123.2,
        "text": "AI的服務器特殊在"
      },
      {
        "start": 123.2,
        "end": 125.04,
        "text": "芯片密集 散熱快"
      },
      {
        "start": 125.04,
        "end": 127.68,
        "text": "NPU普通新片快20倍的高速互聯"
      },
      {
        "start": 127.68,
        "end": 129.56,
        "text": "服務器的價格也非常高"
      },
      {
        "start": 129.56,
        "end": 132.12,
        "text": "一台好的服務器約30萬美元"
      },
      {
        "start": 132.12,
        "end": 134,
        "text": "相當於北京的半套房"
      },
      {
        "start": 134,
        "end": 136.24,
        "text": "OPEN AI需要幾萬台這樣的服務器"
      },
      {
        "start": 136.24,
        "end": 138.96,
        "text": "所以微讓投資100億美元給OPEN AI"
      },
      {
        "start": 138.96,
        "end": 141.16,
        "text": "其實大部分錢就是用來買服務器"
      },
      {
        "start": 141.16,
        "end": 143.24,
        "text": "那普通的公司買不起AI服務器"
      },
      {
        "start": 143.24,
        "end": 145.24,
        "text": "會想加入這個賽道怎麼辦呢"
      },
      {
        "start": 145.24,
        "end": 145.96,
        "text": "哎"
      },
      {
        "start": 145.96,
        "end": 148.76,
        "text": "這眼神出了雲階上的共享經濟模式"
      },
      {
        "start": 148.76,
        "end": 150.36,
        "text": "這是什麼概念呢"
      },
      {
        "start": 150.36,
        "end": 153.44,
        "text": "一個資件服務器前進投入約500公萬"
      },
      {
        "start": 153.44,
        "end": 155.52,
        "text": "但用雲階算按小時付費"
      },
      {
        "start": 155.52,
        "end": 157,
        "text": "可能約50萬左右"
      },
      {
        "start": 157,
        "end": 160.16,
        "text": "所以99%的AI公司都選擇用雲階算"
      },
      {
        "start": 160.16,
        "end": 161.88,
        "text": "國際雲階算3巨頭"
      },
      {
        "start": 161.88,
        "end": 163.07999999999998,
        "text": "一 亞馬遜"
      },
      {
        "start": 163.07999999999998,
        "end": 164.76,
        "text": "市場份額32%"
      },
      {
        "start": 164.76,
        "end": 166.36,
        "text": "最早做雲最成熟"
      },
      {
        "start": 166.36,
        "end": 167.72,
        "text": "和英尾達深度合作"
      },
      {
        "start": 167.72,
        "end": 169.16,
        "text": "提供AI開發平台"
      },
      {
        "start": 169.16,
        "end": 170.4,
        "text": "二 微軟"
      },
      {
        "start": 170.4,
        "end": 172.07999999999998,
        "text": "市場份額23%"
      },
      {
        "start": 172.07999999999998,
        "end": 175.48,
        "text": "靠OPEN AI Power的時搬身IG open AI服務"
      },
      {
        "start": 175.48,
        "end": 179.52,
        "text": "官方和規平台中唯一提供GPT4 API的雲平台"
      },
      {
        "start": 179.52,
        "end": 182.08,
        "text": "優勢和企業軟件深度整合"
      },
      {
        "start": 182.08,
        "end": 183.44,
        "text": "三 骨歌雲"
      },
      {
        "start": 183.44,
        "end": 185.2,
        "text": "市場份額12%"
      },
      {
        "start": 185.2,
        "end": 186.24,
        "text": "技術最強"
      },
      {
        "start": 186.24,
        "end": 187.76,
        "text": "最早用自演TPU"
      },
      {
        "start": 187.76,
        "end": 189.12,
        "text": "但市場做的一般"
      },
      {
        "start": 189.12,
        "end": 189.88,
        "text": "優勢"
      },
      {
        "start": 189.88,
        "end": 191.32,
        "text": "AI研究能力頂尖"
      },
      {
        "start": 191.32,
        "end": 193.08,
        "text": "國內雲計算3巨頭"
      },
      {
        "start": 193.08,
        "end": 194.24,
        "text": "一 阿里雲"
      },
      {
        "start": 194.24,
        "end": 197.36,
        "text": "為電商金融能力預提供企業級的服務"
      },
      {
        "start": 197.36,
        "end": 198.8,
        "text": "二 華為雲"
      },
      {
        "start": 198.8,
        "end": 201.76,
        "text": "基於坤澄澄等自演算力頂做"
      },
      {
        "start": 201.76,
        "end": 203.28,
        "text": "三 橫訊雲"
      },
      {
        "start": 203.28,
        "end": 206.76,
        "text": "一拖微信QQ等吸塞生態"
      },
      {
        "start": 206.76,
        "end": 208.44,
        "text": "它包圍機器學習"
      },
      {
        "start": 208.44,
        "end": 210.4,
        "text": "深度學習而神經網絡"
      },
      {
        "start": 210.4,
        "end": 211.88,
        "text": "是AI的大腦邏輯"
      },
      {
        "start": 211.88,
        "end": 213.44,
        "text": "一 機器學習"
      },
      {
        "start": 213.44,
        "end": 215.64,
        "text": "給它看一萬張貓和狗的圖片"
      },
      {
        "start": 215.64,
        "end": 217.24,
        "text": "它能自己總結出臉圓"
      },
      {
        "start": 217.24,
        "end": 219.56,
        "text": "眼睛大有弧虛的可能是貓"
      },
      {
        "start": 219.56,
        "end": 221.96,
        "text": "核心是從例子中自己學歸率"
      },
      {
        "start": 221.96,
        "end": 223.48,
        "text": "二 深度學習"
      },
      {
        "start": 223.48,
        "end": 225.32,
        "text": "這是機器學習力更厲害"
      },
      {
        "start": 225.32,
        "end": 226.4,
        "text": "更複雜的一種"
      },
      {
        "start": 226.4,
        "end": 228.32,
        "text": "它模仿人道的神經網絡"
      },
      {
        "start": 228.32,
        "end": 230.72,
        "text": "有好幾層甚至幾百層神經園"
      },
      {
        "start": 230.72,
        "end": 233.56,
        "text": "它特別戰場處理海量又複雜的數據"
      },
      {
        "start": 233.56,
        "end": 234.24,
        "text": "比如"
      },
      {
        "start": 234.24,
        "end": 235.36,
        "text": "都玩所要小說"
      },
      {
        "start": 235.36,
        "end": 237.2,
        "text": "自己學會寫適合對話"
      },
      {
        "start": 237.2,
        "end": 238.52,
        "text": "聽完所有的歌曲"
      },
      {
        "start": 238.52,
        "end": 240.2,
        "text": "自己能編出新的旋律"
      },
      {
        "start": 240.2,
        "end": 241.92,
        "text": "三 神經網絡"
      },
      {
        "start": 241.92,
        "end": 244.24,
        "text": "就像我們人道有神經園連接一樣"
      },
      {
        "start": 244.24,
        "end": 245.32,
        "text": "AI的神經網絡"
      },
      {
        "start": 245.32,
        "end": 247.56,
        "text": "也是有一堆的虛擬階點連成的網"
      },
      {
        "start": 247.56,
        "end": 249.68,
        "text": "數據在裡面層層傳遞被處理"
      },
      {
        "start": 249.68,
        "end": 251.68,
        "text": "我們日常接觸的AI工具產品"
      },
      {
        "start": 251.68,
        "end": 252.96,
        "text": "就屬於它的範疇"
      },
      {
        "start": 252.96,
        "end": 254.4,
        "text": "是AI的落地形態"
      },
      {
        "start": 254.4,
        "end": 256.24,
        "text": "例如聊天對話"
      },
      {
        "start": 256.24,
        "end": 257.36,
        "text": "Chat GPT"
      },
      {
        "start": 257.36,
        "end": 258.08,
        "text": "豆包"
      },
      {
        "start": 258.08,
        "end": 258.88,
        "text": "Dipsy"
      },
      {
        "start": 258.88,
        "end": 261.28,
        "text": "用了這深度學習的大語言模型"
      },
      {
        "start": 261.28,
        "end": 262.52,
        "text": "漢華作視頻"
      },
      {
        "start": 262.52,
        "end": 263.2,
        "text": "吉夢"
      },
      {
        "start": 263.2,
        "end": 263.84,
        "text": "Sora"
      },
      {
        "start": 263.84,
        "end": 264.48,
        "text": "Rongway"
      },
      {
        "start": 264.48,
        "end": 267.12,
        "text": "用了這深度學習的圖像深層模型"
      },
      {
        "start": 267.12,
        "end": 268.56,
        "text": "刷臉支付化美妍"
      },
      {
        "start": 268.56,
        "end": 269.6,
        "text": "支付保刷臉"
      },
      {
        "start": 269.6,
        "end": 270.88,
        "text": "手機拍照美妍"
      },
      {
        "start": 270.88,
        "end": 273.44,
        "text": "用了這深度學習的人煉識別模型"
      },
      {
        "start": 273.44,
        "end": 274.4,
        "text": "推薦系統"
      },
      {
        "start": 274.4,
        "end": 275.44,
        "text": "抖音推薦業"
      },
      {
        "start": 275.44,
        "end": 276.68,
        "text": "淘寶餐廳喜歡"
      },
      {
        "start": 276.68,
        "end": 278.84000000000003,
        "text": "用了是機器學習的推薦算法"
      },
      {
        "start": 278.84000000000003,
        "end": 279.76,
        "text": "手機助手"
      },
      {
        "start": 279.76,
        "end": 281.36,
        "text": "Sary 小艾同學"
      },
      {
        "start": 281.36,
        "end": 284.32,
        "text": "背後是語音識別和自然語言的處理模型"
      },
      {
        "start": 284.32,
        "end": 285.76,
        "text": "最後我們用一個造氣車的"
      },
      {
        "start": 285.76,
        "end": 286.88,
        "text": "完整流水性來比喻"
      },
      {
        "start": 286.88,
        "end": 288.15999999999997,
        "text": "做個簡單總結"
      },
      {
        "start": 288.15999999999997,
        "end": 289.2,
        "text": "基礎設施層"
